const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(data[0], 10);
const a = data.slice(1, 1 + n).map(Number);

let visible = 0;
let maxRight = -1;

for (let i = n - 1; i >= 0; i--) {
  if (a[i] > maxRight) {
    visible++;
    maxRight = a[i];
  }
}

console.log(n - visible);
